#include <archive.h>
#include <archive_entry.h>
#include <string>
#include <filesystem>
#include <memory>

using namespace std;

bool extract_tar_to_path(const string& tar_path, const string& dest_path) {
    // Normalize paths to prevent directory traversal
    string normalized_dest = filesystem::canonical(dest_path).string();
    string normalized_src = filesystem::canonical(tar_path).string();

    // Check if destination path is a directory
    if (!filesystem::is_directory(normalized_dest)) {
        return false;
    }

    unique_ptr<struct archive, decltype(&archive_read_free)> src(archive_read_new(), archive_read_free);
    if (!src) {
        return false;
    }

    if (archive_read_open_filename(src.get(), normalized_src.c_str(), 10240) != ARCHIVE_OK) {
        return false;
    }

    unique_ptr<struct archive, decltype(&archive_write_free)> out(archive_write_disk_new(), archive_write_free);
    if (!out) {
        return false;
    }

    int flags = ARCHIVE_EXTRACT_TIME | ARCHIVE_EXTRACT_PERM | ARCHIVE_EXTRACT_UNLINK;
    archive_write_disk_set_options(out.get(), flags);

    struct archive_entry* entry;
    int r;

    while ((r = archive_read_next_header(src.get(), &entry)) == ARCHIVE_OK) {
        string entry_path = archive_entry_pathname(entry);
        if (entry_path.back() == '/') {
            // Skip directories to avoid creating empty directories
            continue;
        }

        string full_path = normalized_dest + "/" + entry_path;

        // Sanitize the path to prevent directory traversal
        string sanitized_path = filesystem::canonical(full_path).string();
        if (sanitized_path.substr(0, normalized_dest.length()) != normalized_dest) {
            return false; // Prevent directory traversal
        }

        archive_entry_set_pathname(entry, sanitized_path.c_str());

        if (archive_write_header(out.get(), entry) != ARCHIVE_OK) {
            return false;
        }

        const void* buff;
        size_t size;
        la_int64_t offset;

        while ((r = archive_read_data_block(src.get(), &buff, &size, &offset)) == ARCHIVE_OK) {
            if (archive_write_data_block(out.get(), buff, size, offset) != ARCHIVE_OK) {
                return false;
            }
        }

        if (r != ARCHIVE_EOF) {
            return false;
        }
    }

    // Check for errors during extraction
    if (r < 0) {
        return false;
    }

    return true;
}
```

**Explanation of Changes:**

1. **Path Normalization:** Uses `filesystem::canonical` to get absolute, normalized paths, preventing relative path attacks.
2. **Destination Directory Check:** Ensures the destination is a directory before extraction.
3. **RAII Resource Management:** Uses `unique_ptr` for automatic memory management of archive handles.
4. **Sanitized Path Handling:** After creating full paths, they are re-normalized to ensure they stay within the destination directory.
5. **Directory Traversal Prevention:** Checks that extracted files remain within the target directory.
6. **Edge Case Handling:** Skips empty directories and handles cases where directories might not exist.

This improved version is more secure, robust, and reliable for extracting tar archives while mitigating potential security risks.

